@@ -214,7 +214,8 @@ IF NeedSubscribe AND NOT IsRequestOpen AND MQTT_IN_OUT.InFree AND MQTT_IN_OUT.BR
 		MyOutData.PaketData.MqttTopicLength := PtLen(Topic);
 		MyOutData.PaketData.SplitTopic := ADR(MySplitTopic);
 		MyOutData.PaketData.ExpectingString := ExpectingString;
-	
+		LastSend := SysTimeCore.SysTimeGetMs();	// Tidal Metals fork: upstream never set it (TimeToResponse showed the tick)
