 		SubscribeFail := FALSE;
 	ELSE
 		NeedSubscribe := FALSE;
@@ -233,6 +234,7 @@ IF NeedUnsubscribe AND NOT IsRequestOpen AND MQTT_IN_OUT.InFree AND MQTT_IN_OUT.
 	MQTT_IN_OUT.InFree := FALSE;
 	MyOutData.PaketData.Callback := Callback;
 	MyOutData.PaketData.MessageType := MESSAGETYPE.UNSUBSCRIBE;
