diff --git a/src/MQTT/Function Blocks/MQTT_CONTROL.st b/src/MQTT/Function Blocks/MQTT_CONTROL.st
index 6494363..7d7dd44 100644
--- a/src/MQTT/Function Blocks/MQTT_CONTROL.st	
+++ b/src/MQTT/Function Blocks/MQTT_CONTROL.st	
@@ -321,8 +321,11 @@ END_IF;
 IF IsProfiled THEN
 	SysTimeCore.SysTimeGetUs(pUsTime := ProfStartUs);
 END_IF
+// Tidal Metals fork: TIME_OUT passed again (upstream's call above had it; without it the TCP layer supervised
+// connect and send with its 200 ms floor, whatever the client's TIMEOUT: a link slower than a LAN disconnected)
 IPC(
-	IP_C:= IP_C, 
+	TIME_OUT:= timeout1,
+	IP_C:= IP_C,
 	S_BUF:= COM.S_BUF, 
 	R_BUF:=COM.R_BUF , 
 	IP:= DWORD#0, 
diff --git a/src/MQTT/Support/Common Helper/IP_CONTROL.st b/src/MQTT/Support/Common Helper/IP_CONTROL.st
index e2fa44f..c61484e 100644
--- a/src/MQTT/Support/Common Helper/IP_CONTROL.st	
+++ b/src/MQTT/Support/Common Helper/IP_CONTROL.st	
@@ -49,6 +49,7 @@ VAR
 	new_connection : BOOL; (* Neue Verbindungsparameter vorhanden *)
 	tx : DWORD; (* letzter zeitwert *)
 	error_time : DWORD; (* aktueller Timeout-Wert *)
+	ElapsedMs : DWORD;	// Tidal Metals fork: a timer's elapsed time, stored first so it wraps at 32 bits on 64-bit targets too
 	//Socket Parameter
 	SysSockParameter:SysSocket2.SysSocket2_Parameter;
 	SysSockSpec : SysSocket2.SysSocket2_SpecificParameter;
@@ -109,8 +110,11 @@ VAR CONSTANT

 	C_WAIT : BYTE:= 250;
 	C_CLOSE : BYTE:= 251;
-	

+	// Tidal Metals fork: a refused connect is only abandoned by this timeout (the non-blocking connect is polled), so
+	// it is capped well below TIME_OUT: an attempt made during an outage retries after 3 s, not 10. 3 s still lets a
+	// slow link connect and survives one lost SYN.
+	CONNECT_TIMEOUT_MAX_MS : DWORD := 3000;
 END_VAR

 (*
@@ -674,13 +678,18 @@ IF IP_C.R_OBSERVE = FALSE OR s_active THEN
     r_time := tx;
 END_IF;

-IF c_status = 0 AND tx - c_time > error_time AND c_enable AND NOT c_ready AND c_mode < 2 THEN (* Connect Timeout *)
+// Tidal Metals fork: each difference is stored in a DWORD before the comparison. 64-bit targets evaluate
+// `tx - c_time` in 64 bits, so across the millisecond counter's wrap (49.7 days) it was huge: an immediate timeout.
+ElapsedMs := tx - c_time;
+IF c_status = 0 AND ElapsedMs > MIN(error_time, CONNECT_TIMEOUT_MAX_MS) AND c_enable AND NOT c_ready AND c_mode < 2 THEN (* Connect Timeout *)
 	c_status := 255; (* Timeout-Fehler ausgeben *)
 END_IF;
-IF s_status = 0 AND tx - s_time > error_time AND s_active THEN (* Send Timeout *)
+ElapsedMs := tx - s_time;
+IF s_status = 0 AND ElapsedMs > error_time AND s_active THEN (* Send Timeout *)
 	s_status := 255; (* Timeout-Fehler ausgeben *)
 END_IF;
-IF r_status = 0 AND tx - r_time > error_time AND c_ready AND IP_C.R_OBSERVE THEN (* Receive Timeout *)
+ElapsedMs := tx - r_time;
+IF r_status = 0 AND ElapsedMs > error_time AND c_ready AND IP_C.R_OBSERVE THEN (* Receive Timeout *)
 	r_status := 255; (* Timeout-Fehler ausgeben *)
 END_IF;
